import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Emulator management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/emulators.md","filePath":"guide/emulators.md","lastUpdated":1787871741000}'),n={name:"guide/emulators.md"};function i(s,e,l,d,m,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="emulator-management" tabindex="-1">Emulator management <a class="header-anchor" href="#emulator-management" aria-label="Permalink to &quot;Emulator management&quot;">​</a></h1><p>The Emulators view manages everything Beholder needs on the device side.</p><h2 id="your-avds" tabindex="-1">Your AVDs <a class="header-anchor" href="#your-avds" aria-label="Permalink to &quot;Your AVDs&quot;">​</a></h2><p>Each AVD shows its device profile, API level, image tag, and two badges:</p><ul><li><strong>rootable</strong> / <strong>no root</strong> — whether the image allows <code>adb root</code>. Google APIs and AOSP images are rootable; Google Play images are not and cannot be inspected by Beholder.</li><li><strong>running</strong> — currently online, with a <strong>Doctor</strong> button</li></ul><h2 id="creating-a-beholder-ready-emulator" tabindex="-1">Creating a Beholder-ready emulator <a class="header-anchor" href="#creating-a-beholder-ready-emulator" aria-label="Permalink to &quot;Creating a Beholder-ready emulator&quot;">​</a></h2><p>The creation wizard encodes everything Beholder requires automatically:</p><ul><li><strong><code>google_apis</code> image</strong> — the only tag that allows <code>adb root</code></li><li><strong><code>arm64-v8a</code></strong> — matches Apple Silicon Macs</li><li>Images are filtered and sorted by API level, newest first</li><li>Missing images download in-app (~1-2 GB) with live progress and automatic license acceptance</li><li>Device profiles come from your SDK&#39;s AVD manager</li></ul><p><strong>Create &amp; Launch</strong> starts the onboarding stepper, which waits for boot, installs the CA, and starts capturing — ending with a direct link to the request list.</p><h2 id="selecting-targets-from-the-command-bar" tabindex="-1">Selecting targets from the command bar <a class="header-anchor" href="#selecting-targets-from-the-command-bar" aria-label="Permalink to &quot;Selecting targets from the command bar&quot;">​</a></h2><p>The emulator dropdown in the command bar lists running emulators first (with a green dot), then stopped AVDs. Selecting a stopped AVD launches it and opens onboarding. <strong>Create emulator</strong> at the bottom jumps to the wizard.</p>',11)])])}const u=a(n,[["render",i]]);export{h as __pageData,u as default};
